174: func (s *Service) observeGreenhouseTasks(ctx context.Context, db *store.DB, project store.Project) error {
175: 	tasks, err := db.Tasks(ctx, project.ID, true)
176: 	if err != nil {
177: 		return err
178: 	}
179: 	for _, task := range tasks {
180: 		if task.MergeMode != "greenhouse" || task.WorktreePath == "" || task.State == store.StateTornDown {
181: 			continue
182: 		}
183: 		watch, err := db.GreenhouseTaskWatch(ctx, task.ID)
184: 		previousStatus := watch.Status
185: 		if err != nil && !store.IsNotFound(err) {
186: 			return err
187: 		}
188: 		runID := watch.RunID
189: 		if runID == "" {
190: 			runID = greenhouseRunIDFromSignals(ctx, db, task)
191: 		}
192: 		var snapshot greenhouseWatchSnapshot
193: 		if runID != "" {
194: 			snapshot = inspectGreenhouseRun(ctx, task, runID)
195: 			if snapshot.RunID == "" {
196: 				snapshot.RunID = runID
197: 			}
198: 		} else {
199: 			snapshot, err = inspectGreenhouseTask(ctx, task)
200: 			if err != nil || snapshot.RunID == "" {
201: 				continue
202: 			}
203: 		}
204: 		stage, status := greenhouseStageLabel(snapshot)
205: 		if status == "" {
206: 			continue
207: 		}
208: 		now := time.Now().UnixMilli()
209: 		runStarted, stageStarted, stageFinished := greenhouseStageTimestamps(snapshot, stage)
210: 		if watch.RunID != snapshot.RunID {
211: 			watch = store.GreenhouseTaskWatch{TaskID: task.ID, RunID: snapshot.RunID, RunObservedAt: now, StageObservedAt: now}
212: 		}
213: 		if stage != watch.Stage {
214: 			watch.StageObservedAt = now
215: 		}
216: 		if runStarted > 0 {
217: 			watch.RunStartedAt = runStarted
218: 		}
219: 		if stageStarted > 0 {
220: 			watch.StageStartedAt = stageStarted
221: 		} else if stage != watch.Stage {
222: 			watch.StageStartedAt = 0
223: 		}
224: 		if stageFinished > 0 {
225: 			watch.StageFinishedAt = stageFinished
226: 		} else if stage != watch.Stage {
227: 			watch.StageFinishedAt = 0
228: 			if stageStarted == 0 {
229: 				watch.StageStartedAt = 0
230: 			}
231: 		}
232: 		watch.Status, watch.Stage, watch.UpdatedAt = status, stage, now
233: 		if err := db.SaveGreenhouseTaskWatch(ctx, watch); err != nil {
234: 			return err
235: 		}
236: 		if previousStatus != watch.Status {
237: 			if err := raiseGreenhouseNotice(ctx, db, project, task, snapshot, previousStatus, watch.Status); err != nil {
238: 				return err
239: 			}
240: 		}
241: 		if !greenhousePaneExists(ctx, s, task, watch.PaneID) {
242: 			watch.PaneID = ""
243: 		}
244: 		if watch.PaneID == "" && watch.Status != "ci-ready" && watch.Status != "locally-ready" && task.HerdrWorkspaceID != "" && s.Herdr != nil {
245: 			paneID, err := s.openGreenhousePane(ctx, task)
246: 			if err == nil {
247: 				watch.PaneID = paneID
248: 				if err := db.SaveGreenhouseTaskWatch(ctx, watch); err != nil {
249: 					return err
250: 				}
251: 			}
252: 		}
253: 		s.reportGreenhouseTaskMetadata(ctx, db, project, task, watch, snapshot)
254: 	}
255: 	return nil
256: }
