func greenhouseRunIDForHead(ctx context.Context, db *store.DB, task store.Task, prURL, head string) (string, error) {
	signals, err := db.TaskSignals(ctx, task.ID, 20)
	if err != nil {
		return "", err
	}
	for _, signal := range signals {
