115: func greenhouseTaskStatus(ctx context.Context, db *store.DB, task store.Task, now time.Time) (string, error) {
116: 	watch, err := db.GreenhouseTaskWatch(ctx, task.ID)
117: 	if store.IsNotFound(err) {
118: 		return "", nil
119: 	}
120: 	if err != nil {
121: 		return "", err
122: 	}
123: 	if watch.Status == "ci-ready" || watch.Status == "locally-ready" {
124: 		return "PR green", nil
125: 	}
126: 	if watch.Status == "needs-decision" {
127: 		return "waiting for decision", nil
128: 	}
129: 	if watch.Status == "failed" || watch.Status == "recovery-required" {
130: 		return "failed: " + watch.Stage, nil
131: 	}
132: 	return greenhouseElapsedSummary(watch, now), nil
133: }
